LM.LAB = {"axes":{"columns":[{"id":"past","label":"Past"},{"id":"present","label":"Present"},{"id":"future","label":"Future"}],"rows":[{"id":"indicative","label":"Indicative"},{"id":"subjunctive","label":"Subjunctive"},{"id":"other","label":"Imperative and conditional"}]},"cards":[{"id":"presente","name":"Presente","nameEn":"Present","column":"present","row":"indicative","level":"A1","summary":"What is true now, what you do regularly, and general facts.","formation":[{"label":"Person order","text":"yo, tú, él / ella / usted, nosotros, vosotros (Spain), ellos / ellas / ustedes"},{"label":"-ar verbs","text":"hablo, hablas, habla, hablamos, habláis, hablan"},{"label":"-er verbs","text":"como, comes, come, comemos, coméis, comen"},{"label":"-ir verbs","text":"vivo, vives, vive, vivimos, vivís, viven"},{"label":"Stem changes (not in nosotros, vosotros)","text":"querer: quiero, quieres… queremos · poder: puedo, puedes… podemos · pedir: pido, pides… pedimos"},{"label":"Irregular yo form","text":"hacer: hago · tener: tengo · salir: salgo · poner: pongo · conocer: conozco"}],"uses":[{"label":"True now","text":"Vivo en un apartamento pequeño cerca del centro.","en":"I live in a small apartment near downtown."},{"label":"Habits and routines","text":"Los sábados juego al tenis con mi hermana.","en":"On Saturdays I play tennis with my sister."},{"label":"General facts","text":"El sol sale por el este.","en":"The sun rises in the east."},{"label":"Happening at the moment","text":"¿Qué haces? —Leo una novela.","en":"What are you doing? —I'm reading a novel."},{"label":"Fixed plans and timetables","text":"Mañana trabajo hasta las ocho.","en":"Tomorrow I'm working until eight."}],"signals":["siempre","normalmente","todos los días","los lunes","a veces","nunca","ahora"],"scenes":[{"id":"habit","label":"Habit","description":"The same action again and again: before now, now and after now.","elements":[{"kind":"repeat","from":-0.9,"to":0.9,"count":7,"label":"every Saturday"}]},{"id":"now","label":"Right now","description":"An action that is going on at the moment of speaking.","elements":[{"kind":"range","from":-0.2,"to":0.2,"label":"I'm reading"}]},{"id":"fact","label":"General fact","description":"Something that is always true, with no start and no end.","elements":[{"kind":"range","from":-0.95,"to":0.95,"label":"always true"}]}],"traps":["English says “I'm reading” for an action going on now. Spanish can just use the present: Leo una novela. Estoy leyendo is also very common, but you do not need it every time.","The ending already shows the person, so the subject pronoun is usually left out: Vivo en Lima. Using yo in every sentence sounds unnatural; keep it for emphasis or contrast.","Stem changes do not happen in the nosotros and vosotros forms: queremos, podemos, not *quieremos, *puedemos."],"contrasts":[{"with":"ir-a-infinitivo","rule":"Both can talk about the future. The present with a time word sounds fixed, like a timetable or an arrangement. Ir a + infinitive puts the plan or intention first.","examples":["El tren sale a las nueve.","Mañana voy a llamar a mi madre."]}],"topicIds":["a1-verbs-present-regular","a1-verbs-present-irregular"],"setTags":["present"]},{"id":"preterito-indefinido","name":"Pretérito indefinido","nameEn":"Preterite","column":"past","row":"indicative","level":"A2","summary":"Finished actions at a definite time in the past.","formation":[{"label":"Person order","text":"yo, tú, él / ella / usted, nosotros, vosotros (Spain), ellos / ellas / ustedes"},{"label":"-ar verbs","text":"hablé, hablaste, habló, hablamos, hablasteis, hablaron"},{"label":"-er and -ir verbs","text":"comí, comiste, comió, comimos, comisteis, comieron"},{"label":"Common irregulars","text":"ser / ir: fui, fuiste, fue… · hacer: hice, hiciste, hizo… · tener: tuve… · estar: estuve…"}],"uses":[{"label":"One finished action","text":"Ayer comí con Lucía.","en":"Yesterday I had lunch with Lucía."},{"label":"A chain of actions","text":"Llegué a casa, cené y me acosté.","en":"I got home, had dinner and went to bed."},{"label":"A closed period of time","text":"Viví tres años en Lima.","en":"I lived in Lima for three years."}],"signals":["ayer","anoche","el lunes","la semana pasada","en 2019","hace dos años"],"scenes":[{"id":"point","label":"Finished action","description":"One completed action at a definite moment before now.","elements":[{"kind":"point","at":-0.5}]},{"id":"chain","label":"Chain of actions","description":"Finished actions one after another, each one moving the story on.","elements":[{"kind":"point","at":-0.75,"label":"got home"},{"kind":"point","at":-0.5,"label":"had dinner"},{"kind":"point","at":-0.25,"label":"went to bed"}]},{"id":"period","label":"Closed period","description":"A period with a clear start and end, completely over now.","elements":[{"kind":"range","from":-0.85,"to":-0.35,"label":"three years in Lima"}]}],"traps":["The English simple past covers both one finished event and a habit: “I ate there yesterday” / “As a kid I ate there every Sunday”. Spanish separates them: comí (once, finished) and comía (habit or background).","Present yo and preterite él differ only by the accent: hablo (I speak) / habló (he or she spoke). The preterite yo form is hablé."],"contrasts":[{"with":"preterito-imperfecto","rule":"Indefinido moves the story forward. Imperfecto paints the background.","examples":["Llovía cuando salí de casa.","De niño jugaba al fútbol; un día me rompí la pierna."]}],"topicIds":["a2-verbs-preterite-regular","a2-verbs-preterite-irregular"],"setTags":["preterite"]},{"id":"preterito-imperfecto","name":"Pretérito imperfecto","nameEn":"Imperfect","column":"past","row":"indicative","level":"A2","summary":"Descriptions, background and habits in the past.","formation":[{"label":"Person order","text":"yo, tú, él / ella / usted, nosotros, vosotros (Spain), ellos / ellas / ustedes"},{"label":"-ar verbs","text":"hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban"},{"label":"-er and -ir verbs","text":"comía, comías, comía, comíamos, comíais, comían"},{"label":"The only irregulars","text":"ser: era, eras, era, éramos, erais, eran · ir: iba, ibas, iba, íbamos, ibais, iban · ver: veía, veías, veía…"}],"uses":[{"label":"Habits in the past","text":"De niña vivía en un pueblo e iba a la escuela a pie.","en":"As a girl I lived in a village and walked to school."},{"label":"Descriptions","text":"La casa era vieja y tenía un jardín enorme.","en":"The house was old and had a huge garden."},{"label":"Background to an event","text":"Hacía frío y llovía cuando llegamos.","en":"It was cold and raining when we arrived."},{"label":"Time and how someone felt","text":"Eran las once y yo tenía mucho sueño.","en":"It was eleven o'clock and I was very sleepy."}],"signals":["antes","de niño / de niña","siempre","todos los veranos","normalmente","mientras","cuando era joven"],"scenes":[{"id":"habit","label":"Past habit","description":"Something that happened again and again in the past and does not happen now.","elements":[{"kind":"repeat","from":-0.95,"to":-0.3,"count":5,"label":"every summer"}]},{"id":"background","label":"Background","description":"A situation going on in the past, with no clear start or end, while something else happened.","elements":[{"kind":"range","from":-0.85,"to":-0.2,"label":"it was raining"},{"kind":"point","at":-0.5,"label":"we arrived"}]},{"id":"description","label":"Description","description":"What a person, place or thing was like at that time.","elements":[{"kind":"open-left","to":-0.3,"label":"the house was old"}]}],"traps":["English “used to play” and “was playing” are both often jugaba in Spanish. The imperfecto covers habits and actions in progress.","The imperfecto does not tell you that an action finished. For one finished event at a definite time, use the indefinido: Ayer vi a Pablo. Ayer veía a Pablo sounds unfinished, as if the story goes on.","Watch the accents: hablábamos (only the nosotros form of -ar verbs), but every -er and -ir form has í: comía, vivíamos."],"contrasts":[{"with":"preterito-indefinido","rule":"Imperfecto describes the scene and what used to happen. Indefinido tells what happened next.","examples":["Cuando era pequeño, pasaba los veranos en la playa.","Un verano conocí a mi mejor amigo."]}],"topicIds":["a2-verbs-imperfect","a2-verbs-preterite-vs-imperfect-basics"],"setTags":["imperfect"]},{"id":"ir-a-infinitivo","name":"ir a + infinitivo","nameEn":"going to + infinitive","column":"future","row":"indicative","level":"A1","summary":"Plans, intentions and things that are clearly about to happen.","formation":[{"label":"Pattern","text":"ir (present) + a + infinitivo"},{"label":"All persons","text":"voy a comer, vas a comer, va a comer, vamos a comer, vais a comer (Spain), van a comer"},{"label":"Negative","text":"No voy a salir esta noche."},{"label":"With a pronoun (two places)","text":"Te voy a llamar. / Voy a llamarte."}],"uses":[{"label":"Plans","text":"Este verano vamos a viajar a Perú.","en":"This summer we're going to travel to Peru."},{"label":"Intentions","text":"El próximo año voy a estudiar más.","en":"Next year I'm going to study more."},{"label":"About to happen (you can see it)","text":"¡Cuidado, te vas a caer!","en":"Careful, you're going to fall!"},{"label":"Let's… (vamos a)","text":"Bueno, vamos a empezar.","en":"OK, let's start."}],"signals":["mañana","esta noche","este fin de semana","el próximo año","la semana que viene","pronto"],"scenes":[{"id":"plan","label":"Plan","description":"You decide now; the action comes later.","elements":[{"kind":"point","at":0.6,"label":"the trip"}]},{"id":"soon","label":"About to happen","description":"You can see now that something will happen very soon.","elements":[{"kind":"point","at":0.15,"label":"about to fall"}]}],"traps":["Do not leave out a: Voy a comer, not *Voy comer.","After a comes the infinitive, never a conjugated verb: Vamos a salir, not *Vamos a salimos.","English “I'm going to the movies” has no second verb. In Spanish that is ir a + a place: Voy al cine."],"contrasts":[{"with":"presente","rule":"Ir a + infinitive puts the plan or intention first. The present with a time word sounds fixed, like a timetable or an arrangement.","examples":["Mañana voy a llamar a mi madre.","El tren sale a las nueve."]}],"topicIds":["a1-verbs-ir-a-infinitive"],"setTags":["ir-a"]},{"id":"preterito-perfecto","name":"Pretérito perfecto","nameEn":"Present perfect","column":"past","row":"indicative","level":"A2","summary":"The past seen from now: experiences, things done or not done yet and, in Spain, today.","formation":[{"label":"Person order","text":"yo, tú, él / ella / usted, nosotros, vosotros (Spain), ellos / ellas / ustedes"},{"label":"haber + participle","text":"he, has, ha, hemos, habéis, han + hablado / comido / vivido"},{"label":"Participles","text":"-ar → -ado (hablado) · -er / -ir → -ido (comido, vivido)"},{"label":"Irregular participles","text":"hecho, dicho, puesto, vuelto, visto, escrito, abierto, roto"}],"uses":[{"label":"Experiences (no time given)","text":"¿Has estado alguna vez en México?","en":"Have you ever been to Mexico?"},{"label":"Already and not yet","text":"Todavía no he comido.","en":"I haven't eaten yet."},{"label":"Never","text":"Nunca he viajado en avión.","en":"I've never traveled by plane."},{"label":"A time that is not over (Spain)","text":"Hoy he trabajado mucho.","en":"I've worked a lot today."}],"signals":["ya","todavía no","aún no","alguna vez","nunca","hoy","esta mañana","esta semana","este año"],"scenes":[{"id":"experience","label":"Experience","description":"Something that happened at some time in your life up to now; when is not important.","elements":[{"kind":"range","from":-0.95,"to":0,"label":"my life so far"},{"kind":"point","at":-0.45,"label":"been to Peru"}]},{"id":"not-yet","label":"Not yet","description":"Something expected that has not happened up to now.","elements":[{"kind":"range","from":-0.6,"to":0,"label":"not yet"},{"kind":"marker","at":0,"label":"now"}]},{"id":"today","label":"Today (Spain)","description":"A finished action inside a time that is not over yet: today, this week, this year.","elements":[{"kind":"range","from":-0.35,"to":0,"label":"today"},{"kind":"point","at":-0.2,"label":"worked a lot"}]}],"traps":["With a finished time (ayer, el año pasado, en 2019) use the preterite everywhere: Ayer vi a Marta, never ayer he visto.","Nothing goes between haber and the participle: Ya he comido (not he ya comido), No lo he visto.","The participle after haber never changes: Ella ha comido, ellos han comido.","Spain vs Latin America: in most of Latin America people use the preterite for today and often for ya and todavía no: Hoy desayuné tarde. ¿Ya comiste?"],"contrasts":[{"with":"preterito-indefinido","rule":"Perfecto looks at the past from now, with no finished time. Indefinido places the action at a finished time.","examples":["¿Has estado alguna vez en Perú?","Estuve en Perú el año pasado."]}],"topicIds":["a2-verbs-present-perfect"],"setTags":["present-perfect"]},{"id":"estar-gerundio","name":"estar + gerundio","nameEn":"be + -ing (in progress)","column":"present","row":"indicative","level":"A2","summary":"An action in progress right now, or a temporary situation these days.","formation":[{"label":"Person order","text":"yo, tú, él / ella / usted, nosotros, vosotros (Spain), ellos / ellas / ustedes"},{"label":"estar + gerund","text":"estoy, estás, está, estamos, estáis, están + hablando / comiendo / escribiendo"},{"label":"Gerunds","text":"-ar → -ando (hablando) · -er / -ir → -iendo (comiendo, viviendo)"},{"label":"Irregular gerunds","text":"leyendo, oyendo, trayendo, yendo · pidiendo, diciendo, sirviendo, viniendo · durmiendo, muriendo"},{"label":"Pronouns","text":"me estoy duchando = estoy duchándome"}],"uses":[{"label":"Right now","text":"Está hablando por teléfono.","en":"She's on the phone."},{"label":"These days","text":"Este mes estamos trabajando mucho.","en":"We're working a lot this month."},{"label":"Today, unlike usual","text":"Normalmente trabajo en casa, pero hoy estoy trabajando en la oficina.","en":"I usually work at home, but today I'm working at the office."}],"signals":["ahora","ahora mismo","en este momento","estos días","hoy"],"scenes":[{"id":"now","label":"Right now","description":"An action that has started and is going on at the moment of speaking.","elements":[{"kind":"range","from":-0.15,"to":0.15,"label":"I'm making dinner"}]},{"id":"these-days","label":"These days","description":"A temporary situation around now, not a permanent one.","elements":[{"kind":"range","from":-0.45,"to":0.45,"label":"this month"}]}],"traps":["Never for future plans: English “I'm leaving tomorrow” is Mañana salgo or Mañana voy a salir.","The helper is estar, never ser: Estoy trabajando.","Verbs for states usually do not take it: Tengo un coche (not estoy teniendo un coche), Sé la respuesta (not estoy sabiendo).","As a noun (“swimming is good”) Spanish uses the infinitive: Nadar es bueno."],"contrasts":[{"with":"presente","rule":"Estar + gerundio stresses that the action is in progress now. The presente is for habits and facts, and can also describe what is happening.","examples":["Normalmente trabajo en casa.","Hoy estoy trabajando en la oficina."]}],"topicIds":["a2-verbs-estar-gerund"],"setTags":["estar-gerund"]},{"id":"futuro-simple","name":"Futuro simple","nameEn":"Future","column":"future","row":"indicative","level":"A2","summary":"Predictions, promises and the more distant future.","formation":[{"label":"Person order","text":"yo, tú, él / ella / usted, nosotros, vosotros (Spain), ellos / ellas / ustedes"},{"label":"infinitive + ending","text":"hablaré, hablarás, hablará, hablaremos, hablaréis, hablarán (the same for -er and -ir)"},{"label":"Irregular stems","text":"tendr-, pondr-, saldr-, vendr-, querr-, har-, dir-, podr-, sabr-, habr- (habrá = there will be)"}],"uses":[{"label":"Predictions","text":"Mañana lloverá en el norte.","en":"It will rain in the north tomorrow."},{"label":"Promises","text":"Te llamaré esta noche.","en":"I'll call you tonight."},{"label":"The more distant future","text":"El año que viene viviremos en Valencia.","en":"Next year we'll live in Valencia."},{"label":"After si + present","text":"Si llueve, nos quedaremos en casa.","en":"If it rains, we'll stay at home."}],"signals":["mañana","pasado mañana","la semana que viene","el año que viene","el próximo año","dentro de dos días","pronto","algún día"],"scenes":[{"id":"prediction","label":"Prediction","description":"What you think will happen later; nothing is decided now.","elements":[{"kind":"point","at":0.55,"label":"it will rain"}]},{"id":"promise","label":"Promise","description":"You decide now and promise an action for later.","elements":[{"kind":"marker","at":0,"label":"I promise"},{"kind":"point","at":0.35,"label":"I'll call you"}]}],"traps":["After si, use the present, not the future: Si llueve, no saldremos (not si lloverá).","Every form has a written accent except nosotros: hablaré, but hablaremos.","Irregular stems are short: haré (not haceré), tendré (not teneré), diré (not deciré).","For an offer right now (“I'll get it!”), Spanish uses the present: ¡Ya voy! Yo te ayudo."],"contrasts":[{"with":"ir-a-infinitivo","rule":"Ir a + infinitivo is the usual choice in conversation for plans already decided. The futuro is typical for predictions and promises.","examples":["Esta tarde voy a ver a Marta.","Algún día tendremos una casa en el campo."]}],"topicIds":["a2-verbs-future-simple"],"setTags":["future"]},{"id":"imperativo","name":"Imperativo","nameEn":"Imperative","column":"present","row":"other","level":"A2","summary":"Instructions, directions, offers and requests: “do this”.","formation":[{"label":"tú","text":"the él / ella form of the present: habla, come, sube, sigue"},{"label":"Eight irregular tú forms","text":"di, haz, ve, pon, sal, sé, ten, ven"},{"label":"usted / ustedes","text":"yo form, drop -o, swap the vowel: hable / hablen, coma / coman, tenga / tengan"},{"label":"Irregular usted forms","text":"vaya, sea, sepa, dé"},{"label":"vosotros (Spain)","text":"infinitive with -d instead of -r: hablad, comed, venid"},{"label":"Pronouns","text":"attached, often with an accent: llámame, dígame, siéntese"}],"uses":[{"label":"Directions","text":"Sigue todo recto y toma la primera a la izquierda.","en":"Go straight ahead and take the first left. (Todo recto is Spain; Latin America: sigue derecho.)"},{"label":"Instructions and recipes","text":"Corta las cebollas y ponlas en la sartén.","en":"Cut the onions and put them in the pan."},{"label":"Offers and invitations","text":"Pasa, pasa. Siéntate.","en":"Come in, come in. Sit down."},{"label":"To a stranger (usted)","text":"Siga por esta calle.","en":"Keep going along this street."}],"signals":["por favor","perdone","perdona","primero","después","al final de la calle"],"scenes":[{"id":"instruction","label":"Instruction","description":"Said now, for an action the listener does right after.","elements":[{"kind":"marker","at":0,"label":"turn right!"},{"kind":"point","at":0.2,"label":"they turn"}]},{"id":"steps","label":"Steps","description":"A chain of instructions, one after the other.","elements":[{"kind":"point","at":0.15,"label":"go straight ahead"},{"kind":"point","at":0.4,"label":"turn left"},{"kind":"point","at":0.65,"label":"cross"}]}],"traps":["The tú form looks like the present: habla, come. Context and tone show it is an instruction.","Ve (go) and ven (come) are easy to mix up: Ve a la tienda. Ven a mi casa.","Pronouns are attached, and the stressed syllable often needs an accent: llámame, not me llama or llamame.","This card is about “do”; “don't” has other forms and comes later."],"contrasts":[{"with":"presente","rule":"The tú imperative looks like the él / ella present, but gives an order. Between friends, a question in the present is often softer.","examples":["Pásame la sal.","¿Me pasas la sal?"]}],"topicIds":["a2-verbs-imperative-affirmative","a2-functions-directions"],"setTags":["imperative"]}],"contrasts":[{"id":"ser-estar","level":"A1","summary":"Two verbs for “to be”: ser says what something is, estar says where it is and how it is right now.","sides":[{"name":"ser","nameEn":"what someone or something is","rules":[{"label":"Identity and jobs","text":"Who or what someone is, including their job.","examples":[{"text":"Soy Marta y soy enfermera.","en":"I'm Marta and I'm a nurse."}]},{"label":"Origin","text":"Where someone or something comes from.","examples":[{"text":"Mis padres son de Bogotá.","en":"My parents are from Bogotá."}]},{"label":"What it is like","text":"Lasting characteristics: personality, looks, size, color.","examples":[{"text":"Tu hermano es muy simpático.","en":"Your brother is very nice."},{"text":"La casa es grande y blanca.","en":"The house is big and white."}]},{"label":"Events","text":"Where or when an event happens: a party, a class, a concert.","examples":[{"text":"La fiesta es en casa de Ana.","en":"The party is at Ana's place."}]},{"label":"Time and dates","text":"The time, the day and the date.","examples":[{"text":"Hoy es lunes y son las cinco.","en":"Today is Monday and it's five o'clock."}]}]},{"name":"estar","nameEn":"where it is and how it is now","rules":[{"label":"Location","text":"Where a person or a thing is, even when it never moves. (Where an event happens takes ser.)","examples":[{"text":"El museo está en el centro.","en":"The museum is downtown."},{"text":"Madrid está en el centro de España.","en":"Madrid is in the center of Spain."}]},{"label":"Feelings and states","text":"How someone feels or what state something is in at the moment.","examples":[{"text":"Estoy cansada porque trabajo mucho.","en":"I'm tired because I work a lot."},{"text":"La ventana está abierta.","en":"The window is open."}]},{"label":"bien and mal","text":"Asking and saying how someone is.","examples":[{"text":"¿Cómo estás? —Estoy bien, gracias.","en":"How are you? —I'm fine, thanks."}]}]}],"tip":"Ask yourself: am I saying what this is, or where it is and how it is right now? What it is → ser. Where it is, or how it is now → estar.","traps":["*Soy cansado → Estoy cansado. Feelings and states take estar.","*Está médico → Es médico. Jobs take ser.","*La farmacia es en esta calle → La farmacia está en esta calle. Location takes estar.","*Soy 20 años → Tengo 20 años. Age takes tener, not ser or estar."],"topicIds":["a1-verbs-ser-vs-estar-basics","a1-verbs-estar-hay","a1-verbs-ser"],"quiz":{"items":[{"id":"lab-ser-estar-q1","type":"multiple-choice","kind":"form","prompt":"Mi madre ___ profesora de inglés.","options":["es","está","tiene","hay"],"correct":0,"explanation":"A job says who someone is, so it takes ser: Mi madre es profesora.","optionNotes":[null,"Estar is not used for jobs.","Tener does not link a person to a job.","Hay means “there is” and does not describe a person."]},{"id":"lab-ser-estar-q2","type":"multiple-choice","kind":"form","prompt":"¿Dónde ___ las llaves? (Where are the keys?)","options":["son","están","es","está"],"correct":1,"explanation":"Location takes estar, and las llaves is plural: ¿Dónde están las llaves?","optionNotes":["Location takes estar, not ser.",null,"Location takes estar, and las llaves is plural.","Estar is right, but las llaves is plural: están."]},{"id":"lab-ser-estar-q3","type":"multiple-choice","kind":"form","prompt":"Ana no va a clase hoy porque ___ enferma.","options":["es","está","tiene","ser"],"correct":1,"explanation":"Being ill is a state at the moment, so it takes estar: Ana está enferma.","optionNotes":["Ser would describe what Ana is like in general, which does not fit an illness today.",null,"Tener needs a noun: tiene fiebre.","Ser is the infinitive; the sentence needs a conjugated verb."]},{"id":"lab-ser-estar-q4","type":"multiple-choice","kind":"form","prompt":"Choose the correct sentence.","options":["Estoy de Valencia, pero ahora soy en Lima.","Soy de Valencia, pero ahora soy en Lima.","Soy de Valencia, pero ahora estoy en Lima.","Estoy de Valencia, pero ahora estoy en Lima."],"correct":2,"explanation":"Origin takes ser (soy de Valencia) and location takes estar (estoy en Lima).","optionNotes":["Both verbs are the wrong way round.","Soy de Valencia is right, but location takes estar: estoy en Lima.",null,"Estoy en Lima is right, but origin takes ser: soy de Valencia."]}]}},{"id":"indefinido-imperfecto","level":"A2","summary":"Two simple past tenses: the indefinido tells what happened, the imperfecto describes the scene and habits.","sides":[{"name":"indefinido","nameEn":"what happened","rules":[{"label":"One finished action","text":"An event at a definite time.","examples":[{"text":"Ayer vi una película muy buena.","en":"Yesterday I saw a very good movie."}]},{"label":"A chain of events","text":"Actions one after the other that move the story on.","examples":[{"text":"Abrí la puerta y entré.","en":"I opened the door and went in."}]},{"label":"A closed period","text":"A period with a clear end, counted as one event.","examples":[{"text":"Viví en Roma tres años.","en":"I lived in Rome for three years."}]},{"label":"The interruption","text":"The new event that cuts into an action in progress.","examples":[{"text":"Dormía cuando sonó el teléfono.","en":"I was sleeping when the phone rang."}]}]},{"name":"imperfecto","nameEn":"the scene and habits","rules":[{"label":"Background","text":"What things were like, the weather, the time, how someone felt.","examples":[{"text":"Hacía sol cuando llegamos a la playa.","en":"It was sunny when we got to the beach."}]},{"label":"Action in progress","text":"Something going on, with no end in view (“was doing”).","examples":[{"text":"Cenábamos cuando llamó Ana.","en":"We were having dinner when Ana called."}]},{"label":"Habits","text":"What used to happen again and again.","examples":[{"text":"De niño iba a la playa todos los veranos.","en":"As a child I went to the beach every summer."}]}]}],"tip":"Think of a film: the imperfecto is the scene in the background, the indefinido is the action that moves the story on.","traps":["*De niño fui a la playa todos los veranos → De niño iba a la playa todos los veranos. A habit takes the imperfecto.","*Cuando llegué, mi madre cocinó (meaning she was in the middle of it) → Cuando llegué, mi madre cocinaba. Cocinó would mean she started cooking after I arrived.","*Ayer veía una película muy buena → Ayer vi una película muy buena. One finished action yesterday.","*Estaba en Roma tres días → Estuve en Roma tres días. A closed period is an event."],"topicIds":["a2-verbs-preterite-vs-imperfect-basics","a2-verbs-imperfect","a2-verbs-preterite-regular"],"quiz":{"items":[{"id":"lab-indefinido-imperfecto-q1","type":"multiple-choice","kind":"form","prompt":"___ las once cuando terminó la película.","options":["Fueron","Eran","Son","Fue"],"correct":1,"explanation":"The time in the past is background, so it takes the imperfecto: Eran las once.","optionNotes":["The time is background, not an event: eran.",null,"Son is the present; the story is in the past.","The time is background, and las once is plural: eran."]},{"id":"lab-indefinido-imperfecto-q2","type":"multiple-choice","kind":"form","prompt":"Ayer estaba muy cansada, así que ___ temprano.","options":["me acostaba","me acosté","me acuesto","me acostaré"],"correct":1,"explanation":"Going to bed early yesterday is one finished event, so it takes the indefinido: me acosté. Being tired is the background (estaba).","optionNotes":["The imperfecto would describe a habit or a background; going to bed yesterday is one event.",null,"Me acuesto is the present.","Me acostaré is the future."]},{"id":"lab-indefinido-imperfecto-q3","type":"multiple-choice","kind":"form","prompt":"Cuando ___ niña, vivía en Cádiz.","options":["fui","estuve","era","estaba"],"correct":2,"explanation":"Childhood is a background description: cuando era niña.","optionNotes":["Childhood is background, not an event: era.","Being a child is what you were, so ser, and background: era.",null,"Being a child is what you were, not a state: ser, so era."]},{"id":"lab-indefinido-imperfecto-q4","type":"multiple-choice","kind":"form","prompt":"Choose the correct sentence.","options":["El año pasado empecé a correr.","El año pasado empezaba a correr una vez.","Antes corrí todos los días.","De repente, empezaba a llover."],"correct":0,"explanation":"Starting something last year is one event: empecé.","optionNotes":[null,"Una vez marks one event, so it takes the indefinido: empecé.","Todos los días is a habit: corría.","De repente marks a sudden event: empezó a llover."]}]}},{"id":"perfecto-indefinido","level":"A2","summary":"Two ways to say what happened: the perfecto looks at the past from now, the indefinido places it at a finished time.","sides":[{"name":"perfecto","nameEn":"the past seen from now","rules":[{"label":"Experiences","text":"Something in your life up to now; when is not said.","examples":[{"text":"¿Has estado alguna vez en México?","en":"Have you ever been to Mexico?"}]},{"label":"Already, not yet","text":"With ya, todavía no, aún no.","examples":[{"text":"Todavía no he visto la película.","en":"I haven't seen the movie yet."}]},{"label":"A time that is not over (Spain)","text":"Hoy, esta mañana, esta semana, este año.","examples":[{"text":"Esta semana hemos ido dos veces al cine.","en":"This week we've been to the movies twice."}]}]},{"name":"indefinido","nameEn":"at a finished time","rules":[{"label":"A finished time","text":"Ayer, anoche, el año pasado, en 2019, hace dos años: everywhere.","examples":[{"text":"Ayer comí paella.","en":"Yesterday I had paella."}]},{"label":"Today in Latin America","text":"In most of Latin America people also use it for today and often for ya and todavía no.","examples":[{"text":"Hoy desayuné tarde. ¿Ya comiste?","en":"I had breakfast late today. Have you eaten yet?"}]}]}],"tip":"Is the time finished (ayer, el año pasado)? → indefinido, everywhere. No time, or a time that goes on until now? → perfecto, especially in Spain.","traps":["*Ayer he visto a Marta → Ayer vi a Marta. Ayer is a finished time.","*He ya comido → Ya he comido. Nothing goes between haber and the participle.","*¿Has hacido la cena? → ¿Has hecho la cena? Hacer has the participle hecho.","Hoy desayuné tarde is not a mistake: it is the normal Latin American form."],"topicIds":["a2-verbs-present-perfect","a2-verbs-preterite-regular"],"quiz":{"items":[{"id":"lab-perfecto-indefinido-q1","type":"multiple-choice","kind":"form","prompt":"El año pasado ___ a Perú con mis padres.","options":["he viajado","viajé","viajo","he viajada"],"correct":1,"explanation":"El año pasado is a finished time, so it takes the indefinido everywhere: viajé.","optionNotes":["A finished time (el año pasado) does not take the perfecto.",null,"Viajo is the present.","A finished time takes the indefinido, and the participle never changes."]},{"id":"lab-perfecto-indefinido-q2","type":"multiple-choice","kind":"form","prompt":"¿___ alguna vez pulpo? (tú, an experience)","options":["He comido","Has comida","Has comido","Has comiendo"],"correct":2,"explanation":"An experience with alguna vez takes the perfecto: has + the participle comido.","optionNotes":["He is for yo; the question is to tú: has.","The participle after haber never changes: comido.",null,"Comiendo is the gerund; the perfecto needs the participle comido."]},{"id":"lab-perfecto-indefinido-q3","type":"multiple-choice","kind":"form","prompt":"Choose the correct sentence.","options":["He ya terminado.","Ayer he terminado el libro.","Ya terminado he.","Ya he terminado."],"correct":3,"explanation":"Ya goes before haber, and nothing goes between haber and the participle: Ya he terminado.","optionNotes":["Nothing goes between haber and the participle.","Ayer is a finished time: terminé.","Haber comes before the participle.",null]},{"id":"lab-perfecto-indefinido-q4","type":"multiple-choice","kind":"form","prompt":"Anoche ___ con mi hermana por teléfono.","options":["hablé","he hablado","hablo","habla"],"correct":0,"explanation":"Anoche is a finished time, so it takes the indefinido: hablé.","optionNotes":[null,"Anoche is a finished time; the perfecto does not fit.","Hablo is the present.","Habla is the present, for él / ella."]}]}},{"id":"por-para","level":"A2","summary":"Two words for English “for”: para looks ahead to a goal, por looks at the cause or the way.","sides":[{"name":"para","nameEn":"the goal","rules":[{"label":"Purpose","text":"para + infinitive: in order to.","examples":[{"text":"Estudio español para viajar.","en":"I study Spanish so I can travel."}]},{"label":"Who gets it","text":"The person something is for.","examples":[{"text":"Este regalo es para ti.","en":"This present is for you."}]},{"label":"Destination","text":"Where you are heading.","examples":[{"text":"El tren para Sevilla sale a las diez.","en":"The train to Seville leaves at ten."}]},{"label":"Deadline","text":"By a time or a day.","examples":[{"text":"Necesito el informe para el lunes.","en":"I need the report by Monday."}]},{"label":"Opinion","text":"para mí: in my view.","examples":[{"text":"Para mí, es demasiado caro.","en":"For me, it's too expensive."}]}]},{"name":"por","nameEn":"the cause and the way","rules":[{"label":"Cause, thanks","text":"Because of; gracias + what you thank someone for takes por.","examples":[{"text":"Gracias por la ayuda.","en":"Thanks for the help."},{"text":"No salimos por la lluvia.","en":"We didn't go out because of the rain."}]},{"label":"Through a place","text":"Through, along, around.","examples":[{"text":"Me gusta pasear por el centro.","en":"I like walking around downtown."}]},{"label":"Means","text":"By phone, by email.","examples":[{"text":"Te llamo por teléfono.","en":"I'll call you on the phone."}]},{"label":"Price","text":"What you pay for something.","examples":[{"text":"Compré la chaqueta por cuarenta euros.","en":"I bought the jacket for forty euros."}]}]}],"tip":"Ask: is it a goal ahead (what for, who for, where to, by when)? → para. Is it the cause or the way (why, through where, how, for how much)? → por.","traps":["*Gracias para el regalo → Gracias por el regalo. Thanks take por.","*Estudio español por viajar → Estudio español para viajar. “In order to” is para.","*Compré el libro para diez euros → Compré el libro por diez euros. The price takes por.","*Viví en Lima para dos años → Viví en Lima dos años. A length of time needs no para."],"topicIds":["a2-grammar-por-para-basics"],"quiz":{"items":[{"id":"lab-por-para-q1","type":"multiple-choice","kind":"form","prompt":"Ahorro dinero ___ comprar una casa.","options":["por","para","a","de"],"correct":1,"explanation":"Purpose (in order to) is para + infinitive.","optionNotes":["Por is for the cause; a purpose takes para.",null,"A is not used for a purpose here.","De does not express a purpose."]},{"id":"lab-por-para-q2","type":"multiple-choice","kind":"form","prompt":"Muchas gracias ___ tu ayuda.","options":["para","a","por","de"],"correct":2,"explanation":"Gracias + what you thank someone for takes por.","optionNotes":["Thanks take por, not para.","A is not used after gracias.",null,"Gracias takes por."]},{"id":"lab-por-para-q3","type":"multiple-choice","kind":"form","prompt":"Pagué veinte euros ___ la camiseta.","options":["por","para","en","con"],"correct":0,"explanation":"The price you pay for something takes por.","optionNotes":[null,"The price takes por, not para.","En is not used for the price you pay.","Con is not used for a price."]},{"id":"lab-por-para-q4","type":"multiple-choice","kind":"form","prompt":"Tengo que terminar el trabajo ___ el viernes.","options":["por","en","de","para"],"correct":3,"explanation":"A deadline (by Friday) takes para.","optionNotes":["A deadline takes para.","En el viernes is not Spanish; the deadline takes para.","De does not mark a deadline.",null]}]}},{"id":"saber-conocer","level":"A2","summary":"Two verbs for English “to know”: saber for facts and skills, conocer for people and places.","sides":[{"name":"saber","nameEn":"facts, information, skills","rules":[{"label":"A fact","text":"Information you have.","examples":[{"text":"Sé su número.","en":"I know his number."}]},{"label":"+ que, si, dónde, cuándo…","text":"Information in a clause.","examples":[{"text":"No sé dónde vive.","en":"I don't know where she lives."}]},{"label":"+ infinitive","text":"A skill you learned.","examples":[{"text":"Mi hijo sabe tocar el piano.","en":"My son can play the piano."}]}]},{"name":"conocer","nameEn":"people, places and things you are familiar with","rules":[{"label":"A person","text":"With personal a.","examples":[{"text":"Conozco a Lucía.","en":"I know Lucía."}]},{"label":"A place","text":"A town, a country, a restaurant.","examples":[{"text":"Conozco Lima muy bien.","en":"I know Lima very well."}]},{"label":"Meeting someone","text":"In the preterite: met for the first time.","examples":[{"text":"Conocí a Laura en el trabajo.","en":"I met Laura at work."}]}]}],"tip":"Can you put “that”, “where” or a skill after it? → saber. Is it a person or a place you have met? → conocer.","traps":["*Sé Madrid / *Sé a tu hermano → Conozco Madrid / Conozco a tu hermano. People and places take conocer.","*No conozco dónde vive → No sé dónde vive. Information after dónde takes saber.","*Conozco nadar → Sé nadar. A skill is saber + infinitive.","Yo forms: sé (with an accent) and conozco."],"topicIds":["a2-grammar-saber-conocer"],"quiz":{"items":[{"id":"lab-saber-conocer-q1","type":"multiple-choice","kind":"form","prompt":"¿___ a mi novio? Te lo presento.","options":["Sabes","Conoces","Sabe","Conozco"],"correct":1,"explanation":"A person takes conocer, with personal a: ¿Conoces a mi novio?","optionNotes":["Saber is for facts and skills, not for people.",null,"Saber is the wrong verb for a person.","Conozco is yo; the question is to tú."]},{"id":"lab-saber-conocer-q2","type":"multiple-choice","kind":"form","prompt":"No ___ a qué hora abre el museo.","options":["conozco","conoce","sé","sabo"],"correct":2,"explanation":"Information after a qué hora takes saber: No sé a qué hora abre.","optionNotes":["Information in a clause takes saber.","Information takes saber, and the subject is yo.",null,"The yo form of saber is sé."]},{"id":"lab-saber-conocer-q3","type":"multiple-choice","kind":"form","prompt":"Mi abuela ___ hablar tres idiomas.","options":["sabe","conoce","sabes","conoces"],"correct":0,"explanation":"A skill is saber + infinitive: sabe hablar.","optionNotes":[null,"A skill takes saber, not conocer.","Sabes is for tú; mi abuela takes sabe.","A skill takes saber, and mi abuela takes the él / ella form."]},{"id":"lab-saber-conocer-q4","type":"multiple-choice","kind":"form","prompt":"___ a mi mejor amiga en el colegio, el primer día de clase.","options":["Supe","Sabía","Conocía","Conocí"],"correct":3,"explanation":"Meeting someone for the first time is conocer in the preterite: Conocí a mi mejor amiga.","optionNotes":["Saber is not used for people.","Saber is not used for people.","Meeting someone is one event, so the preterite: conocí.",null]}]}}],"trees":[{"id":"ser-or-estar","title":"ser or estar?","level":"A1","intro":"Think of the sentence you want to say with “to be”. A few questions lead to the right verb, and sometimes it is neither of the two.","start":"start","nodes":{"start":{"question":"What does “to be” tell us in your sentence?","help":"Pick the closest answer.","options":[{"label":"Where a person or a thing is","result":["ser-estar"],"answer":"estar","why":"Location takes estar, even for places that never move.","example":{"text":"Mi oficina está cerca de la estación.","en":"My office is near the station."}},{"label":"Where an event happens: a party, a class, a concert","result":["ser-estar"],"answer":"ser","why":"Events take ser, also for where they happen.","example":{"text":"La clase es en el aula 3.","en":"The class is in room 3."}},{"label":"Who someone is, their job, or where they are from","result":["ser-estar"],"answer":"ser","why":"Identity, jobs and origin take ser.","example":{"text":"Soy Diego, soy de Quito y soy cocinero.","en":"I'm Diego, I'm from Quito and I'm a cook."}},{"label":"The time, the day or the date","result":["ser-estar"],"answer":"ser","why":"The time and dates take ser.","example":{"text":"Son las tres y media.","en":"It's half past three."}},{"label":"How old someone is","result":["ser-estar"],"answer":"tener","why":"Spanish does not use “to be” for age. Age takes tener.","example":{"text":"Mi hermana tiene quince años.","en":"My sister is fifteen."}},{"label":"What someone is doing right now (“is doing”)","result":["estar-gerundio","ser-estar"],"answer":"estar + gerund","why":"An action in progress takes estar + gerund, never ser.","example":{"text":"Mis hijos están durmiendo.","en":"My children are sleeping."}},{"label":"What a thing is made of","result":["ser-estar"],"answer":"ser","why":"Material is part of what something is: ser de.","example":{"text":"La mesa es de madera.","en":"The table is made of wood."}},{"label":"What someone or something is like, or how they are","next":"describe"}]},"describe":{"question":"Is it what they are like in general, or how they are at the moment?","help":"Would you say it to describe them to someone who has never met them, or about today?","options":[{"label":"What they are like in general: personality, looks, size, color","result":["ser-estar"],"answer":"ser","why":"Lasting characteristics take ser.","example":{"text":"Mi abuelo es alto y muy tranquilo.","en":"My grandfather is tall and very calm."}},{"label":"How they feel or how they are right now: tired, glad, ill, busy","result":["ser-estar"],"answer":"estar","why":"Feelings and states at the moment take estar.","example":{"text":"Hoy estamos muy ocupados.","en":"We're very busy today."}},{"label":"Just “How are you?” or “I'm fine”","result":["ser-estar"],"answer":"estar","why":"Bien and mal go with estar.","example":{"text":"¿Cómo está tu padre? —Está bien, gracias.","en":"How is your father? —He's fine, thanks."}}]}}},{"id":"pick-past-tense","title":"Pick the past tense","level":"A2","intro":"You want to say something about the past. A few questions lead to the indefinido, the imperfecto or the perfecto.","start":"start","nodes":{"start":{"question":"Do you say when it happened?","help":"Look for a time word in your sentence.","options":[{"label":"Yes, a finished time: ayer, anoche, el año pasado, en 2019, hace dos años","next":"finished"},{"label":"Yes, a time that is not over yet: hoy, esta mañana, esta semana","result":["perfecto-indefinido","preterito-perfecto"],"answer":"perfecto (Spain) / indefinido (most of Latin America)","why":"In Spain a time that is not over takes the perfecto; in most of Latin America the indefinido is normal.","example":{"text":"Hoy he trabajado mucho. / Hoy trabajé mucho.","en":"I've worked a lot today."}},{"label":"No, it is about my life up to now: ever, never, already, not yet","result":["preterito-perfecto","perfecto-indefinido"],"answer":"perfecto (much of Latin America: also indefinido with ya / todavía no)","why":"Experiences and things done or not done yet, with no time given, take the perfecto. In many Latin American countries ya and todavía no also go with the indefinido: ¿Ya comiste?","example":{"text":"¿Has estado alguna vez en Perú?","en":"Have you ever been to Peru?"}},{"label":"No, it is a description or a habit: as a child, before, always","next":"scene"}]},"finished":{"question":"Within that finished time, is it an event or the scene?","help":"An event moves the story on. The scene is what things were like or what was going on.","options":[{"label":"An event: something happened, once or a counted number of times","result":["preterito-indefinido","indefinido-imperfecto"],"answer":"indefinido","why":"A finished event at a finished time takes the indefinido.","example":{"text":"Ayer fui al cine con Diego.","en":"Yesterday I went to the movies with Diego."}},{"label":"A closed period: three years, all day, two weeks","result":["preterito-indefinido","indefinido-imperfecto"],"answer":"indefinido","why":"A period with a clear end counts as one event.","example":{"text":"Estuve dos semanas en Perú.","en":"I was in Peru for two weeks."}},{"label":"The scene: the weather, the time, how someone felt, what was going on","result":["preterito-imperfecto","indefinido-imperfecto"],"answer":"imperfecto","why":"The background of a story takes the imperfecto, even inside a finished time.","example":{"text":"Anoche hacía frío y llovía.","en":"Last night it was cold and raining."}}]},"scene":{"question":"What are you describing?","options":[{"label":"What used to happen again and again","result":["preterito-imperfecto","indefinido-imperfecto"],"answer":"imperfecto","why":"Past habits take the imperfecto.","example":{"text":"De niño jugaba en la calle.","en":"As a child I used to play in the street."}},{"label":"What someone or something was like, age or the time","result":["preterito-imperfecto"],"answer":"imperfecto","why":"Descriptions, age and the time in the past take the imperfecto.","example":{"text":"Mi abuela era muy alta y tenía el pelo blanco.","en":"My grandmother was very tall and had white hair."}},{"label":"An action in progress when something else happened","result":["indefinido-imperfecto","preterito-imperfecto"],"answer":"imperfecto + indefinido","why":"The action in progress takes the imperfecto; the event that interrupts it takes the indefinido.","example":{"text":"Dormía cuando sonó el teléfono.","en":"I was sleeping when the phone rang."}}]}}}]};
